INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.72.0',
  '2026-08-05',
  'Товары из чеков по группам, круговая диаграмма и история цен',
  E'Чек больше не сваливается в одну категорию. Трата за поход в магазин остаётся ОДНОЙ строкой, но делится на части: продукты, алкоголь, бытовая химия, доставка. В отчёте появилась круговая диаграмма с легендой — она и список категорий считаются из одного механизма, поэтому двух разных цифр об одних деньгах не бывает, а доли всегда сходятся с суммой траты до копейки.\n\nГруппа товара определяется встроенным словарём: из 23 названий в ваших чеках он узнаёт 21. Всё неопознанное честно висит отдельным куском «Не разобрано» — нажмите на него, чтобы разметить. Размеченное запоминается навсегда и применяется ко всем чекам, включая прошлые: разметили один раз — отчёт стал правильным целиком.\n\nДля незнакомых товаров есть кнопка «Спросить агента»: домашний AI предлагает группы, а применяете их вы — само ничего не меняется.\n\nНовая вкладка «Товары»: на что уходят деньги по товарам, сколько раз брали и как менялась цена за единицу. Доставку и сервисный сбор видно отдельной группой — понятно, сколько в месяц стоит само удобство доставки.\n\nЛюбую трату теперь можно разложить по категориям вручную, не только чек из письма.',
  E'Доли траты — finance_tx_splits (миграция 0091). Ключевое: отчёт берёт их LEFT JOIN-ом (у траты с разбивкой строка на каждую долю, у остальных одна строка с суммой целиком), поэтому круговая диаграмма и отчёт по категориям — ОДИН механизм, а месячные итоги не меняются. Фильтр ленты по категории тоже смотрит в доли, иначе переход из отчёта в ленту терял бы разложенные чеки.\n\nСведение обязательно: доли масштабируются (сумма позиций не сходится с subtotal — каталожные цены против факта), суммы округляются, поэтому остаток от округления отдаётся самой крупной доле. Сборы за доставку идут отдельной долей, а не размазываются.\n\nОпределение группы слоями: память решений (finance_item_rules, ключ — нормализованное название + магазин) → встроенный словарь подстрок (internal/receipts/groups.go) → «Не разобрано» (доля с NULL-категорией). Ручное решение словарём не перетирается. Соответствие встроенных групп категориям пользователя хранится в finance_item_groups: свои деревья у всех разные, угадывать по названию нельзя. SeedItemGroups переиспользует существующую категорию с тем же именем, а не плодит вторую.\n\nПрименение решения идёт по ВСЕМ чекам (ApplyItemRuleEverywhere) с пересборкой долей затронутых трат: иначе разметка чинила бы только будущее.\n\nAI-подсказки — поверх существующей инфраструктуры ai_tasks/ai_runs: строгий промпт, ответ парсится от первой «[» до последней «]» (модели обрамляют JSON пояснениями и ```-блоками), неизвестные группы отбрасываются. Ничего не применяется без человека.\n\nИстория цен — цена за единицу (amount/qty): количество в чеках плавает (вес, штуки). Название нормализуется без отбрасывания объёма: «0.5l» и «0.33l» — разные товары с разной ценой.\n\nПроверено на трёх настоящих чеках: словарь разложил 10 из 11 позиций первого чека, доли сошлись с тратой (16027.46 = 16027.46), ручная разметка Kvass убрала «Не разобрано» в ноль и увеличила «Алкоголь» ровно на его сумму, баланс счёта от разбивки не изменился; в браузере — диаграмма с легендой, вкладка «Товары», история цены пива (585/ед. в обоих чеках, ×1 и ×6).'
);
